def float Pd1max = 0.0;
def float Pd2max = 0.0;
def float Pbat_Pmax = 0.0;
def float Pg_req = 0.0;
def float Pbat_discharge = 0.0;
def float Pbat_charge = 0.0;
def float Pspare = 0.0;
def int cmd_LNG = 0;
def int cmd_DG1 = 0;
def int cmd_DG2 = 0;
def int cmd_load_cutin = 0;
def int cmd_load_cutout = 0;

state LNGShipEMS {
    ! * -> ZeroLoadCharge : if [PL == 0 && SoC < 0.95];
    ! * -> ZeroLoadSpare : if [PL == 0 && SoC >= 0.95];
    ! * -> RESCoversCharge : if [PL > 0 && Ppv + Pw >= PL && SoC < 0.95];
    ! * -> RESCoversSpare : if [PL > 0 && Ppv + Pw >= PL && SoC >= 0.95];
    ! * -> BatteryDischarge : if [PL > 0 && Ppv + Pw < PL && SoC >= 0.2 && PL - Ppv - Pw <= Pbat_Pmax];
    ! * -> LNGWithChargeMargin : if [PL > 0 && Ppv + Pw < PL && SoC < 0.2 && PL - Ppv - Pw + Pgmax / 5 <= eng3_Pmax];
    ! * -> LNGOnly : if [PL > 0 && Ppv + Pw < PL && PL - Ppv - Pw <= eng3_Pmax && (SoC < 0.2 || PL - Ppv - Pw > Pbat_Pmax) && (SoC >= 0.2 || PL - Ppv - Pw + Pgmax / 5 > eng3_Pmax)];
    ! * -> LNGBattery : if [PL > 0 && Ppv + Pw < PL && SoC >= 0.2 && PL - Ppv - Pw > eng3_Pmax && PL - Ppv - Pw <= eng3_Pmax + Pbat_Pmax];
    ! * -> LNGDG1WithChargeMargin : if [PL > 0 && Ppv + Pw < PL && SoC < 0.2 && PL - Ppv - Pw > eng3_Pmax && PL - Ppv - Pw + Pd1max / 10 <= eng3_Pmax + Pd1max];
    ! * -> LNGDG1 : if [PL > 0 && Ppv + Pw < PL && PL - Ppv - Pw > eng3_Pmax && PL - Ppv - Pw <= eng3_Pmax + Pd1max && (SoC >= 0.2 || PL - Ppv - Pw + Pd1max / 10 > eng3_Pmax + Pd1max) && (SoC < 0.2 || PL - Ppv - Pw > eng3_Pmax + Pbat_Pmax)];
    ! * -> AllThermal : if [PL > 0 && Ppv + Pw < PL && PL - Ppv - Pw > eng3_Pmax + Pd1max && PL - Ppv - Pw <= eng3_Pmax + Pd1max + Pd2max];
    ! * -> OverloadBatteryCover : if [PL > 0 && Ppv + Pw < PL && PL - Ppv - Pw > eng3_Pmax + Pd1max + Pd2max];

    [*] -> ZeroLoadCharge;

    state ZeroLoadCharge {
        during {
            Pg_req = 0.0;
            Pbat_discharge = 0.0;
            Pbat_charge = Ppv + Pw;
            Pspare = 0.0;
            cmd_LNG = 0;
            cmd_DG1 = 0;
            cmd_DG2 = 0;
            cmd_load_cutin = 1;
            cmd_load_cutout = 0;
        }
    }

    state ZeroLoadSpare {
        during {
            Pg_req = 0.0;
            Pbat_discharge = 0.0;
            Pbat_charge = 0.0;
            Pspare = Ppv + Pw;
            cmd_LNG = 0;
            cmd_DG1 = 0;
            cmd_DG2 = 0;
            cmd_load_cutin = 1;
            cmd_load_cutout = 0;
        }
    }

    state RESCoversCharge {
        during {
            Pg_req = 0.0;
            Pbat_discharge = 0.0;
            Pbat_charge = Ppv + Pw - PL;
            Pspare = 0.0;
            cmd_LNG = 0;
            cmd_DG1 = 0;
            cmd_DG2 = 0;
            cmd_load_cutin = 1;
            cmd_load_cutout = 0;
        }
    }

    state RESCoversSpare {
        during {
            Pg_req = 0.0;
            Pbat_discharge = 0.0;
            Pbat_charge = 0.0;
            Pspare = Ppv + Pw - PL;
            cmd_LNG = 0;
            cmd_DG1 = 0;
            cmd_DG2 = 0;
            cmd_load_cutin = 1;
            cmd_load_cutout = 0;
        }
    }

    state BatteryDischarge {
        during {
            Pg_req = 0.0;
            Pbat_discharge = PL - Ppv - Pw;
            Pbat_charge = 0.0;
            Pspare = 0.0;
            cmd_LNG = 0;
            cmd_DG1 = 0;
            cmd_DG2 = 0;
            cmd_load_cutin = 1;
            cmd_load_cutout = 0;
        }
    }

    state LNGWithChargeMargin {
        during {
            Pg_req = PL - Ppv - Pw + Pgmax / 5;
            Pbat_discharge = 0.0;
            Pbat_charge = Pgmax / 5;
            Pspare = 0.0;
            cmd_LNG = 1;
            cmd_DG1 = 0;
            cmd_DG2 = 0;
            cmd_load_cutin = 1;
            cmd_load_cutout = 0;
        }
    }

    state LNGOnly {
        during {
            Pg_req = PL - Ppv - Pw;
            Pbat_discharge = 0.0;
            Pbat_charge = 0.0;
            Pspare = 0.0;
            cmd_LNG = 1;
            cmd_DG1 = 0;
            cmd_DG2 = 0;
            cmd_load_cutin = 1;
            cmd_load_cutout = 0;
        }
    }

    state LNGBattery {
        during {
            Pg_req = eng3_Pmax;
            Pbat_discharge = PL - Ppv - Pw - eng3_Pmax;
            Pbat_charge = 0.0;
            Pspare = 0.0;
            cmd_LNG = 1;
            cmd_DG1 = 0;
            cmd_DG2 = 0;
            cmd_load_cutin = 1;
            cmd_load_cutout = 0;
        }
    }

    state LNGDG1WithChargeMargin {
        during {
            Pg_req = PL - Ppv - Pw + Pd1max / 10;
            Pbat_discharge = 0.0;
            Pbat_charge = Pd1max / 10;
            Pspare = 0.0;
            cmd_LNG = 1;
            cmd_DG1 = 1;
            cmd_DG2 = 0;
            cmd_load_cutin = 1;
            cmd_load_cutout = 0;
        }
    }

    state LNGDG1 {
        during {
            Pg_req = PL - Ppv - Pw;
            Pbat_discharge = 0.0;
            Pbat_charge = 0.0;
            Pspare = 0.0;
            cmd_LNG = 1;
            cmd_DG1 = 1;
            cmd_DG2 = 0;
            cmd_load_cutin = 1;
            cmd_load_cutout = 0;
        }
    }

    state AllThermal {
        during {
            Pg_req = PL - Ppv - Pw;
            Pbat_discharge = 0.0;
            Pbat_charge = 0.0;
            Pspare = 0.0;
            cmd_LNG = 1;
            cmd_DG1 = 1;
            cmd_DG2 = 1;
            cmd_load_cutin = 1;
            cmd_load_cutout = 0;
        }
    }

    state OverloadBatteryCover {
        during {
            Pg_req = eng3_Pmax + Pd1max + Pd2max;
            Pbat_discharge = PL - Ppv - Pw - eng3_Pmax - Pd1max - Pd2max;
            Pbat_charge = 0.0;
            Pspare = 0.0;
            cmd_LNG = 1;
            cmd_DG1 = 1;
            cmd_DG2 = 1;
            cmd_load_cutin = 1;
            cmd_load_cutout = 0;
        }
    }
}
